from datetime import date, timedelta

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> (borrower, borrow_date) or None if available
        self.user_borrows = {}  # user -> list of (book_id, borrow_date, return_date_or_None, fine)
        self.user_fines = {}  # user -> total unpaid fine amount

    def add_book(self, book_id: str) -> None:
        if book_id not in self.books:
            self.books[book_id] = None  # available

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")
        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        self.books[book_id] = (user, day)

        if user not in self.user_borrows:
            self.user_borrows[user] = []
        self.user_borrows[user].append((book_id, day, None, 0.0))

        # Initialize user fines if not present
        if user not in self.user_fines:
            self.user_fines[user] = 0.0

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")
        if self.books[book_id] is None:
            raise ValueError(f"Book {book_id} is not borrowed")
        if self.books[book_id][0] != user:
            raise ValueError(f"Book {book_id} was not borrowed by user {user}")

        # Find the borrow record for this user and book
        borrow_record = None
        borrow_index = -1
        for i, (b_id, b_day, r_day, fine) in enumerate(self.user_borrows[user]):
            if b_id == book_id and r_day is None:
                borrow_record = (b_id, b_day, r_day, fine)
                borrow_index = i
                break

        if borrow_record is None:
            raise ValueError(f"Book {book_id} was not borrowed by user {user}")

        # Calculate fine
        borrow_date = borrow_record[1]
        due_date = borrow_date + timedelta(days=self.loan_days)
        fine = 0.0

        # Count business days (excluding weekends) from due_date + 1 to return_date (inclusive)
        if day > due_date:
            # Count delay days (only weekdays)
            delay_days = 0
            current = due_date + timedelta(days=1)
            while current <= day:
                # Monday=0, Sunday=6, so weekend is 5 and 6
                if current.weekday() < 5:  # Monday to Friday
                    delay_days += 1
                current += timedelta(days=1)

            fine = delay_days * self.daily_fine

        # Update the borrow record with return date and fine
        self.user_borrows[user][borrow_index] = (book_id, borrow_date, day, fine)

        # Update user's total unpaid fine
        self.user_fines[user] = self.unpaid_fines(user)

        # Mark book as available
        self.books[book_id] = None

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.user_borrows:
            return 0.0

        total_fine = 0.0
        for book_id, borrow_date, return_date, fine in self.user_borrows[user]:
            if return_date is None:
                # Book is still borrowed, check if it's overdue
                due_date = borrow_date + timedelta(days=self.loan_days)
                if date.today() > due_date:
                    # Count business days of delay
                    delay_days = 0
                    current = due_date + timedelta(days=1)
                    while current <= date.today():
                        if current.weekday() < 5:
                            delay_days += 1
                        current += timedelta(days=1)
                    total_fine += delay_days * self.daily_fine
            else:
                # Book has been returned, but fine might be unpaid
                total_fine += fine

        return total_fine

    def pay(self, user: str) -> None:
        if user in self.user_fines:
            self.user_fines[user] = 0.0
